CREATE TEMPORARY TABLE m_draw AS SELECT a.season, a.j AS team, SUM(a.pts / o.v) AS v FROM m_A a JOIN m_o8 o ON o.season = a.season AND o.team = a.i GROUP BY a.season, a.j;
