CREATE TEMPORARY TABLE m_r1 AS SELECT q.grp, q.i, q.v - m.mu AS v FROM m_q1 q JOIN m_m1 m ON m.grp = q.grp;
ALTER TABLE m_r1 ADD INDEX (grp, i);
